import{_ as l,a0 as n,w as a,s as f,I as t,x as o,a1 as i,A as s,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"Firefox 在過去 12 年裏損失了 5 億用户及其 75% 份額的原因 | LCTT x X-CMD","titleTemplate":false,"description":"Firefox 在過去 12 年裏損失了 5 億用户及其 75% 份額的原因 | LCTT (202109) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Firefox 在過去 12 年裏損失了 5 億用户及其 75% 份額的原因 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Firefox 在過去 12 年裏損失了 5 億用户及其 75% 份額的原因 | LCTT (202109) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202109/20210911 Here-s Why Firefox is Seeing a Continuous Decline for Last 12 Years","title":"Firefox 在過去 12 年裏損失了 5 億用户及其 75% 份額的原因","tag":"202109","desc":""},"relativePath":"202109/20210911 Here-s Why Firefox is Seeing a Continuous Decline for Last 12 Years.md","filePath":"[post].md"}'),d={name:"202109/20210911 Here-s Why Firefox is Seeing a Continuous Decline for Last 12 Years.md"};function u(m,e,x,C,b,F){const r=n("Link");return a(),f("div",null,[e[21]||(e[21]=t("h1",{id:"firefox-在過去-12-年裏損失了-5-億用户及其-75-份額的原因",tabindex:"-1"},[o("Firefox 在過去 12 年裏損失了 5 億用户及其 75% 份額的原因 "),t("a",{class:"header-anchor",href:"#firefox-在過去-12-年裏損失了-5-億用户及其-75-份額的原因","aria-label":"Permalink to “Firefox 在過去 12 年裏損失了 5 億用户及其 75% 份額的原因”"},"​")],-1)),e[22]||(e[22]=t("blockquote",null,[t("p",null,"一位有四十年編程經驗的老程序員表達了他對 Firefox 瀏覽器為何逐漸衰退的看法。")],-1)),e[23]||(e[23]=t("p",null,[t("img",{src:"https://i2.wp.com/news.itsfoss.com/wp-content/uploads/2021/09/decline.png?w=1200&ssl=1",alt:""})],-1)),t("p",null,[e[1]||(e[1]=o("最近有很多關於 Firefox 瀏覽器衰落的討論，還有很多討論 ",-1)),i(r,{href:"https://news.itsfoss.com/firefox-decline/"},{default:s(()=>[...e[0]||(e[0]=[o("它在過去兩年裏失去了 5000 萬用户",-1)])]),_:1}),e[2]||(e[2]=o(" 的文章。",-1))]),e[24]||(e[24]=t("p",null,[o("但是 "),t("strong",null,"實際上它的衰落已經有 12 年之久了，總共損失了 5 億用户和它曾經擁有的市場份額的 75%"),o("。")],-1)),e[25]||(e[25]=t("p",null,"這一切都開始於 2009 年第三季度，其致命的決定是強迫……",-1)),e[26]||(e[26]=t("h3",{id:"頂部標籤",tabindex:"-1"},[o("頂部標籤 "),t("a",{class:"header-anchor",href:"#頂部標籤","aria-label":"Permalink to “頂部標籤”"},"​")],-1)),t("p",null,[e[4]||(e[4]=o("自從 ",-1)),i(r,{href:"https://www.wired.com/2009/07/mozilla-considers-copying-chrome-for-firefox-4dot0/"},{default:s(()=>[...e[3]||(e[3]=[o("做了這個決定",-1)])]),_:1}),e[5]||(e[5]=o("，Firefox 就開始丟失市場份額。PC 上的所有程序都使用針對活動窗口的標籤。如微軟 Office 和 Adobe 這樣的專有軟件，如 GIMP、3D 設計、視頻編輯器、十六進制編輯器這樣的 FOSS 軟件，你能想的的種種軟件都是這樣的，這是標準的、合乎邏輯的設計。",-1))]),e[27]||(e[27]=p('<p>然後，谷歌決定將標籤放在其 Chrome 瀏覽器的頂部，該瀏覽器是為移動設備而非台式機設計的。在智能手機上，這可能是有意義的，因為沒有空間來容納一個完整的桌面風格的菜單佈局。但在桌面上，它是反直覺的，並且會破壞與所有其他程序的工作流程。台式機的代碼與手機不同，所以沒有合理的理由試圖將移動用户界面強加給台式機用户，而台式機是 Firefox 的主要用户羣。在一個 400 萬行的代碼庫中，由兩行代碼所制定的單一設置“太難維護”的論點，只是在侮辱用户的智商。代碼不是草坪，如果你幾周不管它，它也不會改變。</p><p>當用户對這一變化的投訴蜂擁而至時，我從一位不願透露姓名的主要開發者那裏得到的回應是：“我們有數億用户。5000 人的抱怨並不代表大多數的用户。”這些投訴有一個共同的觀點：“如果我想讓我的瀏覽器看起來像 Chrome，我就會使用 Chrome。”於是他們就這麼做了。</p><h3 id="不斷刪除-沒人使用-的功能" tabindex="-1">不斷刪除“沒人使用”的功能 <a class="header-anchor" href="#不斷刪除-沒人使用-的功能" aria-label="Permalink to “不斷刪除“沒人使用”的功能”">​</a></h3><p>對 Firefox 所做的每項改動都是一樣的做法。默認功能被改變了，但有一個菜單設置可以恢復它。然後菜單設置被刪除，你只能通過<code>about:config</code> 來改變它。再然後，<code>about:config</code> 選項也被刪除了。用户羣的每一次抗議都得到了同樣的回應：“你只是極少數人，大多數人喜歡這種改變。”</p><p>75% 並不是少數人。幾乎每個人都討厭這些變化，每一次變化都會把更多的用户趕走，而 Mozilla 工作人員傲慢的、居高臨下的回應讓用户們有苦難言，讓他們再也不想回來了。仔細觀察，你可以看到每次刪除一些功能，用户數量都有明顯的下降，只有在第三方組件或 CSS 恢復了這些變化時才會穩定下來。一次又一次，年復一年。他們沒有學到任何教訓。</p><p>光是移除設置還不夠。Firefox 繼續閹割附加組件和主題，強迫集中籤名，並最終廢除了 XUL，而沒有足夠的 Web 擴展 API 來替代失去的功能。在抱怨這一變化時，我再次與一位主要開發者（同一個人）交談。他的回答是（原話）“人們並不是因為附加組件而使用 Firefox 的。我們的遙測顯示 80% 的用户從未安裝過任何附加組件。”也就是説，任何懂技術的人都會立即關閉遙測，因為他們不想讓瀏覽器監視他們，對此我們也曾無數次抱怨過。</p><p>即使是他們在用户界面設計方面的一項重大舉措，即可拖放定製的 Australis 界面，也因為可怕的默認佈局和缺乏不需要 CSS 的選項而疏遠了更多用户。難看的斜角標籤（抄襲自 Chrome）是 Mozilla 唯一承認糟糕的用户界面變化，而且令人驚訝的是，他們只是在 Chrome 取消了斜角標籤 <strong>之後</strong> 才這樣做。</p><p>時至今日，Mozilla 仍然聲稱要聽取用户的意見，但 12 年後，他們仍然無視我們，難看的默認 Proton 用户界面是最新強加給不情願的用户羣的愚蠢選擇。（如果你認為我屬於少數的話，可以在谷歌上輸入 “Firefox Proton” 來查看最常搜索的建議。）幸運的是，它仍然可以用 <code>userChrome.css</code> 來大致修復，但即使是我，也已經厭倦了必須反覆修補新的代碼來跟上不斷的棄用和格式變化。</p><h3 id="糟糕的編碼範式" tabindex="-1">糟糕的編碼範式 <a class="header-anchor" href="#糟糕的編碼範式" aria-label="Permalink to “糟糕的編碼範式”">​</a></h3><p>Mozilla 的源代碼是一場噩夢。例如，默認配置文件的位置被定義了 3 次，使用了 3 種不同的語言的不同的變量，其中之一是由位於不同文件中的多個變量組合生成的。我看到的另外一個例子是在 6 個不同的文件中定義的另一個全局變量。</p><p>在編譯後，下載歷史、訪問過的網頁、書籤等等，都被一起塞進了亂七八糟的文件中。最終的結果是什麼？試着從你的歷史記錄中刪除 400 個條目，看看它需要多長時間。而從一個單獨的文本文件中刪除這麼多行，只需要一瞬間。想改變一個圖標的外觀或為自定義搜索添加一個新的圖標？它們大多隻是 PNG，但它們被混淆並被封入 <code>omni.ja</code> 文件。本來可以用你選擇的編輯器在幾秒鐘內改變，但你需要安裝和學習 Eclipse 之類的程序，並在每次更改時重新編譯文件。這樣的例子不勝枚舉。</p><p>難怪 Mozilla 的碼農在尋找和修復錯誤方面這麼困難。這導致了更糟糕的編碼範式，為了修復錯誤而記錄一切。它部分導致了...</p><h3 id="糟糕的內存管理" tabindex="-1">糟糕的內存管理 <a class="header-anchor" href="#糟糕的內存管理" aria-label="Permalink to “糟糕的內存管理”">​</a></h3><p>如果一個程序坐在那裏什麼都不做，它的內存使用量不應該改變。看看我的內存管理器，我有 40 個進程在遵守這個原則。儘管什麼都不做，卻不斷地讀寫磁盤的唯一程序是什麼？Firefox。它正在運行 13 個進程，所有這些進程都在不斷地做這兩件事。我寫了 40 年的代碼，造了 30 年的電腦，所以我確實瞭解一點計算機如何工作的事情。這就是基礎層面上的糟糕設計，在表面上做再多的修補也無濟於事。</p><p>代碼範式是 Mozilla 性能問題的根源，他們不會解決這個問題。我敢打賭，這也是 FirefoxOS 失敗的原因，它是一個偉大的想法，但由於執行不力和編碼實踐問題，導致太多的錯誤無法修復而失敗。</p><h3 id="在告訴我們-我們重視你的隱私-的同時-侵犯了你的隱私" tabindex="-1">在告訴我們“我們重視你的隱私”的同時，侵犯了你的隱私 <a class="header-anchor" href="#在告訴我們-我們重視你的隱私-的同時-侵犯了你的隱私" aria-label="Permalink to “在告訴我們“我們重視你的隱私”的同時，侵犯了你的隱私”">​</a></h3><p>就是遙測。當你點擊“禁用遙測”時，隱藏的遙測並沒有被禁用。首次運行也要發出遙測信號。強制簽署附加組件。無法關閉的自動更新，每 10 分鐘發出一次信號。需要單獨選擇退出的“實驗”。現在最新的問題是，只是為了製作一個自定義的主題，就強制使用基於 2FA 的應用以登錄到 Firefox 插件帳户，如果不是強制簽署附加組件，根本就不需要。</p><p>Mozilla 對用户隱私的尊重和對我們意見的尊重一樣少。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>事情不一定是這樣的。雖然還沒有，但是不能承認自己的錯誤，也不考慮不同的意見的人，註定要停滯不前，走向衰敗。Mozilla 的決策者似乎就是這樣想的，所以我對未來不抱什麼希望。希望你們中的一些人至少能從他們的錯誤中學習，在他們失敗的地方取得成功。通過為用户提供他們想要的東西，而不是告訴他們應該想要什麼來取得成功。通過提供市場上缺少的東西，而不是盲目地試圖複製你的競爭對手。</p><p><em>本文所表達的觀點和意見僅代表作者本人，不一定反映本站和 It&#39;s FOSS 的官方政策或立場。</em></p><blockquote><p>作者信息：Dan 來自澳大利亞墨爾本，已經有大約 40 年的編碼經驗，做了 25 年的平面設計。他還從事基於 3D 打印機套件的開源機械設計。</p></blockquote><hr>',23)),t("p",null,[e[7]||(e[7]=o("via: ",-1)),i(r,{href:"https://news.itsfoss.com/firefox-continuous-decline/"},{default:s(()=>[...e[6]||(e[6]=[o("https://news.itsfoss.com/firefox-continuous-decline/",-1)])]),_:1})]),t("p",null,[e[12]||(e[12]=o("作者：",-1)),i(r,{href:"https://news.itsfoss.com/author/team/"},{default:s(()=>[...e[8]||(e[8]=[o("Community",-1)])]),_:1}),e[13]||(e[13]=o(" 選題：",-1)),i(r,{href:"https://github.com/lujun9972"},{default:s(()=>[...e[9]||(e[9]=[o("lujun9972",-1)])]),_:1}),e[14]||(e[14]=o(" 譯者：",-1)),i(r,{href:"https://github.com/wxy"},{default:s(()=>[...e[10]||(e[10]=[o("wxy",-1)])]),_:1}),e[15]||(e[15]=o(" 校對：",-1)),i(r,{href:"https://github.com/wxy"},{default:s(()=>[...e[11]||(e[11]=[o("wxy",-1)])]),_:1})]),t("p",null,[e[18]||(e[18]=o("本文由 ",-1)),i(r,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[16]||(e[16]=[o("LCTT",-1)])]),_:1}),e[19]||(e[19]=o(" 原創編譯，",-1)),i(r,{href:"https://linux.cn/"},{default:s(()=>[...e[17]||(e[17]=[o("Linux中國",-1)])]),_:1}),e[20]||(e[20]=o(" 榮譽推出",-1))])])}const S=l(d,[["render",u]]);export{h as __pageData,S as default};
